					}
				}
			}
			if (item == AdventureEncounterSlotType.Minion)
			{
				if (levelConfig.MinionFormation != null && levelConfig.MinionFormation.Any())
				{
					FormationPresence formationPresence3 = levelConfig.MinionFormation.WeightedRandomSelect();
