public override void ProcessGameEvent(GameWorldEvent evt, object data)
	{
		if ((evt == GameWorldEvent.GameSessionInitializationCompleted || evt == GameWorldEvent.GameDaysChanged) && GameWorld.instance.PlayerProfile.GetProgress().Reputation >= 10000.0)
		{
			bool flag = GameWorld.instance.PlayerProfile.GetProgress().Quests.Any((Quest q) => q.QuestIdentifier == QuestIdentifier.Heresy_p1);
			if (!GameWorld.instance.PlayerProfile.GetProgress().Quests.Any((Quest q) => q.QuestIdentifier == QuestIdentifier.Heresy_p2) && !flag)
			{
				GenerateP1();
			}
		}
		if (evt != GameWorldEvent.QuestCompleted || !(data is QuestCompletedEvent))
		{
			return;
		}
		QuestCompletedEvent questCompletedEvent = data as QuestCompletedEvent;
		if (questCompletedEvent.Quest.QuestIdentifier == QuestIdentifier.Heresy_p2)
		{
			bool flag2 = GameWorld.instance.PlayerProfile.GetProgress().Quests.Any((Quest q) => q.QuestIdentifier == QuestIdentifier.Heresy_p1);
			bool flag3 = GameWorld.instance.PlayerProfile.GetProgress().Quests.Any((Quest q) => q.QuestIdentifier == QuestIdentifier.Heresy_p2);
			if (!flag2 && !flag3)
			{
				GenerateP1();
			}
		}
		if (questCompletedEvent.Quest.QuestIdentifier == QuestIdentifier.Heresy_p1)
		{
			bool flag4 = GameWorld.instance.PlayerProfile.GetProgress().Quests.Any((Quest q) => q.QuestIdentifier == QuestIdentifier.Heresy_p1);
			bool flag5 = GameWorld.instance.PlayerProfile.GetProgress().Quests.Any((Quest q) => q.QuestIdentifier == QuestIdentifier.Heresy_p2);
			if (!flag4 && !flag5)
			{
				ResetDropFinal();
				List<AdventureType> list = new List<AdventureType>();
				list.Add(AdventureType.BuriedTemple);
				list.Add(AdventureType.HellishPath);
				list.Add(AdventureType.NorthernTerritory);
				list.Add(AdventureType.ImperialMausoleum);
				List<AdventureType> list2 = list;
				AdventureType adventureType = list2[UnityEngine.Random.Range(0, list2.Count)];
				int currentAchievedLevel = GameWorld.instance.PlayerProfile.GetDungeonRecord(adventureType).CurrentAchievedLevel;
				int level = UnityEngine.Random.Range(1, currentAchievedLevel + 1);
				AdventureLevelConfiguration adventureLevelConfiguration = adventureType.GetAdventureLevelConfiguration(level).NakedDuplicate();
				adventureLevelConfiguration.BossSpawnTable = new List<MonsterAppearance>
				{
					new MonsterAppearance(100, UnitClass.BlueDemonDragon)
				};
				adventureLevelConfiguration.NumberOfRounds = 15;
				adventureLevelConfiguration.EnemyAmountInBattleFromInclusive = 6;
				adventureLevelConfiguration.EnemyAmountInBattleToExclusive = 7;
				adventureLevelConfiguration.NumberOfMinionsPerRound = 0;
				adventureLevelConfiguration.DungeonEffects = GetRandomDungeonEffects(2);
				adventureLevelConfiguration.BossFormations = new List<FormationPresence>();
				adventureLevelConfiguration.CustomizedIdentityCode = Guid.NewGuid().ToString();
				Quest quest = Quest.CreateCustomQuest(QuestIdentifier.Heresy_p2, new List<QuestRewardBase>
				{
					GuaranteedDirectResourceReward.CreateDirectResourceReward(GetNumberOfDungeonResource() * 8, ResourceType.FragmentOfDemon),
					GuaranteedDirectResourceReward.CreateDirectResourceReward(GetNumberOfDungeonResource() * 10000, ResourceType.Money),
					GuaranteedDirectResourceReward.CreateDirectResourceReward(GetNumberOfDungeonResource() * 8, ResourceType.InfusedPowder)
				}, new List<QuestRequirementBase>
				{
					new CustomizedDungeonThroughRequirementLogic
					{
						fullfilled = false,
						DungeonType = adventureType,
						Configuration = adventureLevelConfiguration,
						DifficultyMeasurement = GameWorld.instance.PlayerProfile.GetProgress().MaxAchievedDifficultyValue - 2.0,
						IsTwistedTimeDungeon = false
					}
				}, QualityGrade.Ancient, 300);
				GameWorld.instance.PlayerProfile.AddQuest(quest);
			}
		}
	}

private void GenerateP1()
	{
		PopulateP1(AdventureType.WoodenForest, ResourceType.CrystalOfWoodenForest);
		PopulateP1(AdventureType.MistForest, ResourceType.InkOfMistForest);
		PopulateP1(AdventureType.SnowMountain, ResourceType.IceOfSnowMountain);
		PopulateP1(AdventureType.BuriedTemple, ResourceType.SealOfBuriedTemple);
		PopulateP1(AdventureType.HellishPath, ResourceType.StoneOfHellishPath);
		PopulateP1(AdventureType.ImperialMausoleum, ResourceType.LeafOfImperialM);
		PopulateP1(AdventureType.NorthernTerritory, ResourceType.SandOfNorthernTerritory);
	}

private void PopulateP1(AdventureType dungeonType, ResourceType dungeonResource)
	{
		int currentAchievedLevel = GameWorld.instance.PlayerProfile.GetDungeonRecord(dungeonType).CurrentAchievedLevel;
		int level = UnityEngine.Random.Range(1, currentAchievedLevel + 1);
		AdventureLevelConfiguration adventureLevelConfiguration = dungeonType.GetAdventureLevelConfiguration(level).NakedDuplicate();
		adventureLevelConfiguration.NumberOfRounds = 12;
		adventureLevelConfiguration.EnemyAmountInBattleFromInclusive = 6;
		adventureLevelConfiguration.EnemyAmountInBattleToExclusive = 7;
		adventureLevelConfiguration.NumberOfMinionsPerRound = 0;
		adventureLevelConfiguration.DungeonEffects = GetRandomDungeonEffects(1);
		adventureLevelConfiguration.BossFormations = new List<FormationPresence>();
		adventureLevelConfiguration.CustomizedIdentityCode = Guid.NewGuid().ToString();
		Quest quest = Quest.CreateCustomQuest(QuestIdentifier.Heresy_p1, new List<QuestRewardBase>
		{
			GuaranteedDirectResourceReward.CreateDirectResourceReward(GetNumberOfDungeonResource(), dungeonResource),
			GuaranteedDirectResourceReward.CreateDirectResourceReward(GetNumberOfDungeonResource() * 3, ResourceType.FragmentOfDemon)
		}, new List<QuestRequirementBase>
		{
			new CustomizedDungeonThroughRequirementLogic
			{
				fullfilled = false,
				DungeonType = dungeonType,
				Configuration = adventureLevelConfiguration,
				DifficultyMeasurement = GameWorld.instance.PlayerProfile.GetProgress().MaxAchievedDifficultyValue - 1.0,
				IsTwistedTimeDungeon = false
			}
		}, QualityGrade.Ancient, 300);
		GameWorld.instance.PlayerProfile.AddQuest(quest);
	}

