public AdventureLevelConfiguration GetLevel(int dungeonLevel)
	{
		double difficultyValue = GetDifficultyValue(dungeonLevel);
		DifficultyLevelMeasurement difficultyLevelMeasurementForDungeonRelated = DifficultyLevelMeasurement.GetDifficultyLevelMeasurementForDungeonRelated(difficultyValue);
		BattleEncounterRangeConfiguration encounterRangeConfiguration = difficultyLevelMeasurementForDungeonRelated.GetEncounterRangeConfiguration();
		AdventureLevelConfiguration adventureLevelConfiguration = new AdventureLevelConfiguration();
		adventureLevelConfiguration.LevelNumber = dungeonLevel;
		adventureLevelConfiguration.BossSpawnTable = GetPossibleBossClasses(dungeonLevel);
		adventureLevelConfiguration.BossFormations = GetBossFormations(difficultyLevelMeasurementForDungeonRelated);
		adventureLevelConfiguration.CompletionReputation = difficultyLevelMeasurementForDungeonRelated.CorrespondingReputation;
		adventureLevelConfiguration.MiniBossSpawnTable = GetPossibleMinibossClasses(dungeonLevel);
		adventureLevelConfiguration.MinionSpawnTable = GetPossibleMinionClasses(dungeonLevel);
		adventureLevelConfiguration.EnemyAmountInBattleToExclusive = encounterRangeConfiguration.EnemyAmountInBattleExclusiveTo;
		adventureLevelConfiguration.EnemyAmountInBattleFromInclusive = encounterRangeConfiguration.EnemyAmountInBattleInclusiveFrom;
		adventureLevelConfiguration.NumberOfRounds = encounterRangeConfiguration.NumberOfRounds;
		adventureLevelConfiguration.NumberOfMinionsPerRound = 2;
		adventureLevelConfiguration.DungeonEffects = new List<ISpecialEffectDataLoad>();
		adventureLevelConfiguration.CustomizedIdentityCode = string.Empty;
		adventureLevelConfiguration.MiniBossFormation = GetMinibossFormation(difficultyLevelMeasurementForDungeonRelated);
		adventureLevelConfiguration.MinionFormation = GetMinionFormation(difficultyLevelMeasurementForDungeonRelated);
		return adventureLevelConfiguration;
	}

