public double GetDifficultyValue(int dungeonLevel)
	{
		return StartingDifficultyLevel + (double)dungeonLevel * DifficultyLevelMeasurement.DefaultDifficultyGapPerDungeonLevelIncrement;
	}

public int GetCorrespondingMaxVisibleLevel(double difficultyValue)
	{
		if (difficultyValue <= StartingDifficultyLevel)
		{
			return 1;
		}
		return (int)((difficultyValue - StartingDifficultyLevel) / DifficultyLevelMeasurement.DefaultDifficultyGapPerDungeonLevelIncrement);
	}

public static int GetMaxAchieveableLevel(this AdventureType type)
	{
		if (type == AdventureType.Endless_Entry)
		{
			return 1000000;
		}
		LevelConfigurationBase configuration = type.GetConfiguration();
		return DifficultyLevelMeasurement.GetMaxNumberOfLevels(configuration.StartingDifficultyLevel, configuration.EndingDifficultyLevel);
