			DifficultyLevelMeasurement difficultyLevelMeasurementByDungeonLevel = DifficultyLevelMeasurement.GetDifficultyLevelMeasurementByDungeonLevel(i, type, GameWorld.instance.PlayerProfile.GetStarRating());
