private void GenerateGuide(GameWorldEvent evt, object data)
	{
		if (evt == GameWorldEvent.QuestCompleted && data is QuestCompletedEvent && IsSide2StillRelevant())
		{
			QuestCompletedEvent questCompletedEvent = data as QuestCompletedEvent;
			if (questCompletedEvent.Quest.QuestIdentifier == QuestIdentifier.Side_2 && GameWorld.instance.PlayerProfile.Buildings.Select((KeyValuePair<TownSlot, IBuildingProfile> b) => b.Value).FirstOrDefault((IBuildingProfile b) => b != null && b.BuildingType == BuildingType.Shop) is Shop shop)
			{
				shop.AddCommodities(new List<Commodity>
				{
					new Commodity
					{
						ResourceType = ResourceType.GuideToFarm,
						Amount = 1,
						NumberOfDaysTillExpiration = 99999,
						Items = new List<Item>(),
						PricePerItem = 5000.0
					}
				});
			}
		}
		if (evt == GameWorldEvent.BuildingConstructed && ResourceType.DirtyBadge.HasObtained() && IsSide2StillRelevant() && data is BuildingBuiltEvent buildingBuiltEvent && buildingBuiltEvent.Building is Shop)
		{
			Shop shop2 = buildingBuiltEvent.Building as Shop;
			if (!ResourceType.GuideToFarm.HasObtained())
			{
				shop2.AddCommodities(new List<Commodity>
				{
					new Commodity
					{
						ResourceType = ResourceType.GuideToFarm,
						Amount = 1,
						NumberOfDaysTillExpiration = 99999,
						Items = new List<Item>(),
						PricePerItem = 5000.0
					}
				});
			}
		}
	}

private void QuestIssueCheck(GameWorldEvent evt, object data)
	{
		if (evt != GameWorldEvent.AdventureCompleted || QuestIdentifier.Side_2.QuestHasBeenIssued(GameWorld.instance.PlayerProfile.GetStarRating()) || !(data is Adventure) || !IsSide2StillRelevant())
		{
