public override IEnumerable ProcessAdventureEvent(BroadcastEvent evt)
	{
		IEnumerator enumerator = Part2Issue(evt).GetEnumerator();
		try
		{
			while (enumerator.MoveNext())
			{
				yield return enumerator.Current;
			}
		}
		finally
		{
			IDisposable disposable2;
			IDisposable disposable = (disposable2 = enumerator as IDisposable);
			if (disposable2 != null)
			{
				disposable.Dispose();
			}
		}
	}

private IEnumerable Part2Issue(BroadcastEvent evt)
	{
		int maxSoul = 20;
		if (evt.EventType != AdventureEventType.UnitKilled || evt.EventTriggeringUnit.IsPlayer || !evt.EventTriggeringUnit.IsBoss() || GameWorld.instance.PlayerProfile.QuestChainCompleted(QuestChainIdentifier.ImmortalCult, GameWorld.instance.PlayerProfile.GetStarRating()) || !ResourceType.BlackBead.HasObtained() || GetSoulCollected() >= maxSoul || QuestIdentifier.Side_4_p2.QuestHasBeenIssued(GameWorld.instance.PlayerProfile.GetStarRating()))
		{
			yield break;
		}
		int numberOfSouls = GetSoulCollected() + 1;
		UpdateSoulCollected(numberOfSouls);
		IEnumerator enumerator = GameWorld.instance.BroadCastAdventureEvent(new BroadcastEvent(evt.EventTriggeringUnit, AdventureEventType.BlackBeadSoulCollected, numberOfSouls)).GetEnumerator();
		try
		{
			while (enumerator.MoveNext())
			{
				yield return enumerator.Current;
			}
		}
		finally
		{
			IDisposable disposable2;
			IDisposable disposable = (disposable2 = enumerator as IDisposable);
			if (disposable2 != null)
			{
				disposable.Dispose();
			}
		}
		if (numberOfSouls == maxSoul)
		{
			AddP2();
		}
	}

